        "Locās kā noteiktais artikuls der: Nominatīv dieser/diese/dieses, Akuzatīv diesen (vīr. dz.), Datīv diesem/dieser/diesem. Daudzskaitlī: diese, diesen. Neitrālā forma dieses Jahr nozīmē 'šogad'.",
