        "Pirms uzvārda Frau nozīmē 'kundze': Guten Tag, Frau Berger! Teikums meine Frau parasti nozīmē 'mana sieva', ja runā par ģimeni.",
        "Vienskaitlī pats vārds Frau nemainās, mainās tikai artikuls: die Frau, der Frau."
