        "Salīdzinājuma pakāpes: leiser (klusāk), am leisesten. Pirms lietvārda tai pievieno galotni: eine leise Stimme, leise Musik. Bieži lieto kā apstākļa vārdu: Die Kinder sprechen leise.",
